// Build the record to insert into failed_scan_queue
const item = $input.first().json;

const partialData = {
  instructor:  item.instructor  ?? '',
  subject:     item.subject     ?? '',
  ay_semester: item.ay_semester ?? '',
  remarks:     item.remarks     ?? '',
  date:        item.date        ?? '',
  student_id:  item.student_id  ?? '',
  ratings:     item.ratings     ?? null,
  summary:     item.summary     ?? null,
};

return [{
  json: {
    task_id:       item.task_id       ?? null,
    user_id:       item.user_id       ?? null,
    term_id:       item.term_id       ?? null,
    table_found:   item.table_found   ?? false,
    grid_source:   item.grid_source   ?? 'fallback',
    n8n_ocr_image: item.n8n_ocr_image ?? null,
    status:        'pending',
    partial_data:  partialData,
  }
}];
